package main

// rfcStoryCounts tallies stories by lifecycle bucket for an RFC's progress
// label: total, done, and open (everything not done). Closed stories are
// terminal won't-do work, so they drop out of the total entirely rather than
// inflating it and making an otherwise-finished RFC look unfinished.
func rfcStoryCounts(stories []story) (total, done, open int) {
	for _, s := range stories {
		switch s.Status {
		case "closed":
			continue
		case "done":
			total++
			done++
		default:
			total++
			open++
		}
	}
	return total, done, open
}
